style.css:
@-moz-document domain("unipr.esse3.cineca.it") {
.l-content-container, 
.record-h2, 
body, 
footer, 
.masthead_menu.is-open,
.record{
  background-color: #222 !important;
  color: #e1e1e1 !important;
  border-radius: 10px !important;
}

#boxEsitoProva {
    border-top: 5px solid #413d82;
}

#esse3 .record, body.secondaryMenuBottom .masthead {
  border-color: #413d82;
  border-radius: 10px
}

#esse3 dl.record-riga dt, #esse3 dl.record-riga dd {
border-top: 1px solid #413d82;
}

.pagetitle_title:after {
  background: #413d82;
  border-radius: 10px 
}


dl.record-riga dt, dl.record-riga dd {
  padding-left: 10px !important
}

.pagetitle_title {
  color: #e1e1e1 !important;
}

.masthead {
    background: url(https://unipr.esse3.cineca.it/img/layout/logo_dx.png) no-repeat 90% center / 240px auto, #001224;
}

#secondary-menu {
  background-color: #5b5b5b !important;
    border-radius: 10px !important
}

#secondary-menu li a {
 color: #dedede !important;
}


.masthead_hamburger, .masthead_hamburger:hover, .masthead_hamburger:focus {
  color: #413d82; 
}

#box-item-anchorboxEsitoProva-1-1-img {
  margin-left: 10px !important;
  border-radius: 6px !important;
  opacity: 70% !important
}

.l-content-container a {
    color: #00e0ff;
  font-weight: bolder !important
}

.l-content-container a:hover {
    color: #009bb1;
  font-weight: bolder !important
}

















.fa.fa-2x.fa-times::before {
  color: #413d82 !important
}

/* Contenitore principale */
.masthead_menu_container {
  background: #1e1e2f !important;
  color: #f5f5f5 !important;
  border-radius: 10px !important;
  max-width: 320px;
  overflow-y: auto;
}

/* Header */
.masthead_menu_header {
  background: #2a2b3d !important;
  padding: 10px !important;
  border-radius: 10px !important;
}

/* Menu utente */
.masthead_usermenu {
  background: #2a2b3d !important;
  padding: 8px !important;
  border-radius: 20px !important;
  margin-top: 10px !important;
  color: #e1e1e1 !important;
    border-left: 8px solid #b0b0b0;
  border-bottom: 8px solid #b0b0b0
}

.masthead_usermenu img{
  border-radius: 8px !important;
}

.masthead_usermenu_menu a{
    color: #e1e1e1 !important
}

/* Voci del menu principale */
.masthead_menu_body ul > li > a {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  color: #ddd !important;
  background: #1e1e2f !important;
  text-decoration: none !important;
  padding: 10px 12px !important;
  border-radius: 6px !important;
  transition: background 0.2s ease-in-out;
  border-bottom: 1px solid rgba(255,255,255,0.1) !important;
}
.masthead_menu_body ul > li > a:hover {
  background: #3b3d55 !important;
  color: #fff !important;
}

/* Submenu */
.masthead_menu_body ul ul {
  margin-left: 10px !important;
  border-left: 2px solid #3b3d55 !important;
  background: #252638 !important;
  border-radius: 6px !important;
}
.masthead_menu_body ul ul a {
  font-size: 0.9em !important;
  padding: 8px 10px !important;
  color: #ccc !important;
}
.masthead_menu_body ul ul a:hover {
  background: #444a66 !important;
  color: #fff !important;
}

/* Icone */
.masthead_menu_body i {
  color: #aaa !important;
}

/* Rimuove la barra rossa a sinistra */
.masthead_menu_body ul {
  border-left: none !important;
}

/* Elimina il bordo/grigio attorno agli elementi */
.masthead_menu_body li {
  background: none !important;
  border: none !important;
}

/* Voci di menu dark uniformi */
.masthead_menu_body ul > li > a {
  background: #2a2b3d !important;
  color: #f5f5f5 !important;
  border-radius: 8px !important;
  margin: 6px 0 !important;
  box-shadow: none !important;
}

/* Hover */
.masthead_menu_body ul > li > a:hover {
  background: #3b3d55 !important;
  color: #ffffff !important;
}

/* Icone freccia (fa-chevron) chiare */
.masthead_menu_body i.fa-chevron-left,
.masthead_menu_body i.fa-chevron-right {
  color: #f5f5f5 !important;
}

/* Submenu */
.masthead_menu_body ul ul {
  background: #232435 !important;
  border-left: 2px solid #3b3d55 !important;
  padding-left: 5px !important;
  border-radius: 6px !important;
}
.masthead_menu_body ul ul a {
  background: transparent !important;
  color: #ccc !important;
}
.masthead_menu_body ul ul a:hover {
  background: #3b3d55 !important;
  color: #fff !important;
}






















.app-box_dati_esito_voto {
  background-color: #25272b !important 
}

dd {
  background-color: #222 !important;
  color: #e1e1e1 !important;
  border-radius: 0 10px 10px 0px  !important;
}

dt {
  background-color: #222 !important;
  color: #e1e1e1 !important;
  border-radius: 10px 0px 0px 10px  !important;
    border-left: 1px solid #413d82;
}

#boxMedie ul {
    background-color: #222 !important;
  color: #e1e1e1 !important;
  border-radius: 10px !important;
}

h1, h2 {
    color: #e1e1e1 !important;
}







/* Contenitore tabella */
table {
  width: 100% !important;
  border-collapse: collapse !important;
  background-color: #1e1e2f !important; /* sfondo dark */
  color: #e0e0e0 !important;
  font-family: "Segoe UI", Roboto, Arial, sans-serif !important;
  border-radius: 12px !important;
  overflow: hidden !important;
  box-shadow: none !important; /* tolta ombra */
}

table img {
  border-radius: 6px
}

/* Header */
table thead,
table thead tr,
table thead th {
  background-color: #27293d !important; /* sfondo header forzato */
  color: #f1f1f1 !important;
  border-bottom: 2px solid #2e2e42 !important;
  padding: 14px 12px !important;
  text-align: left !important;
  font-weight: 600 !important;
  font-size: 14px !important;
  letter-spacing: 0.5px !important;
}

/* Celle */
table td {
  padding: 12px 10px !important;
  font-size: 14px !important;
  border-bottom: 1px solid #2e2e42 !important;
  background-color: #1e1e2f !important;
  color: #e0e0e0 !important;
}

table th {
  padding: 12px 10px !important;
  font-size: 14px !important;
  border-bottom: 1px solid #2e2e42 !important;
  background-color: #1e1e2f !important;
  color: #e0e0e0 !important;
}

/* Link */
table a {
  color: #00e0ff !important;
  text-decoration: none !important;
}

/* Icone */
table img {
  filter: brightness(0.9) contrast(1.1) !important;
}

/* Paginazione e filtri */
.footable-pagination,
.footable-filtering {
  background-color: #1e1e2f !important;
  color: #d1d1d1 !important;
  padding: 10px !important;
  border-top: 1px solid #2e2e42 !important;
}

.footable-pagination a,
.footable-filtering input,
.footable-filtering select {
  background: #2b2d42 !important;
  border: none !important;
  border-radius: 6px !important;
  color: #e0e0e0 !important;
  padding: 6px 10px !important;
  margin: 0 4px !important;
}


#esse3 .table-1 td {
    margin: 0;
    padding: 5px;
   border: none !important;
  border-left: 1px solid #2e2e42 !important;
}

#esse3 .table-1 tr {
    margin: 0;
    padding: 5px;
   border: 1px solid #2e2e42 !important
}

#esse3 .table-1 th {
  border-left: 1px solid #4a4a6a;
}















/* Contenitore filtro */
.form-inline,
.footable-filtering-search {
  background-color: #1e1e2f !important;
  color: #e0e0e0 !important;
  border: none !important;
  border-radius: 8px !important;
}

/* Input di ricerca */
.footable-filtering-search input.form-control {
  background-color: #2b2d42 !important;
  border: 1px solid #2e2e42 !important;
  color: #e0e0e0 !important;
  border-radius: 10px !important;
  box-shadow: none !important;
  
}

.footable-filtering-search input.form-control::placeholder {
  color: #9baacf !important;
}

/* Pulsanti */
.footable-filtering-search .btn {
  border: none !important;
  border-radius: 10px !important;
  padding: 6px 12px !important;
}

.footable-filtering-search .btn-primary {
  background-color: #3a82f7 !important;
  color: #fff !important;
}

.footable-filtering-search .btn-default,
.footable-filtering-search .dropdown-toggle {
  background-color: #2b2d42 !important;
  color: #e0e0e0 !important;
}

/* Icone */
.footable-filtering-search .fooicon {
  color: #fff !important;
}

/* Dropdown menu */
.footable-filtering-search .dropdown-menu {
  background-color: #27293d !important;
  border: 1px solid #2e2e42 !important;
  border-radius: 6px !important;
}

.footable-filtering-search .dropdown-menu li a,
.footable-filtering-search .dropdown-menu li label {
  color: #e0e0e0 !important;
  background: none !important;
}

.footable-filtering-search .dropdown-header {
  color: #9baacf !important;
  font-size: 13px !important;
}

.footable-filtering-search .dropdown-menu input[type="checkbox"] {
  accent-color: #3a82f7 !important; /* colore checkbox moderno */
}


.footable-filtering-search .btn-primary {
    background-color: #1b3968 !important;
    color: #e1e1c2 !important;
}

th.footable-first-visible {
  border-radius: 10px 0 0 0 !important;
}

th.footable-last-visible {
    border-radius: 0 10px 0 0 !important;
}

caption {
  color: #e1e1e1
}








/* Stile per browser basati su WebKit (Chrome, Edge, Safari) */
::-webkit-scrollbar {
  width: 8px !important;   /* larghezza verticale */
  height: 8px !important;  /* altezza orizzontale */
}

::-webkit-scrollbar-track {
  background: #1e1e2f !important; /* sfondo track */
}

::-webkit-scrollbar-thumb {
  background-color: #3b3d55 !important; /* barra scura */
  border-radius: 10px !important;
}

::-webkit-scrollbar-thumb:hover {
  background-color: #4a4d6a !important; /* leggermente più chiaro in hover */
}

/* Firefox */
* {
  scrollbar-width: thin !important;       /* sottile */
  scrollbar-color: #3b3d55 #1e1e2f !important; /* thumb / track */
}



#tasse-textPagoPA img{
  border-radius: 20px;
  filter: opacity(70%)
}

.btn-default {
    color: #333333;
    background-color: #273355;
    border-color: #414d97;
  transition: all 0.3s ease-in-out;
}


.btn-default:hover{
    color: #333333;
    background-color: #4d4f94;
    border-color: #101372;
}
}
